#!/usr/bin/env bash
set -euo pipefail

# Simulador de generador de logs masivos por streaming
generate_logs() {
    python3 -c '
import random, time
statuses = [200, 200, 200, 201, 400, 404, 500, 502, 503]
for i in range(500000):
    status = random.choice(statuses)
    latency = round(random.uniform(5.0, 850.0), 2)
    print(f"2026-09-28T12:00:00Z 192.168.1.{i%255} GET /api/v1/resource {status} {latency}")
'
}

echo "Iniciando procesamiento por streaming sin almacenamiento intermedio en disco..."
generate_logs | awk '
    # Condicion de filtrado: Columna 5 es un codigo 5xx
    $5 ~ /^5[0-9]{2}$/ {
        error_count[$5]++
        total_errors++
        total_latency += $6
    }
    END {
        printf("\n--- RESUMEN DE PROCESAMIENTO (STREAMING) ---\n")
        printf("Total errores 5xx detectados: %d\n", total_errors)
        if (total_errors > 0) {
            printf("Latencia promedio en errores: %.2f ms\n", total_latency / total_errors)
            printf("Desglose por codigo:\n")
            for (code in error_count) {
                printf("  HTTP %s: %d errores\n", code, error_count[code])
            }
        }
    }
'
